import{_ as e,o as r,c as a,a2 as i}from"./chunks/framework.DqYch1Cg.js";const f=JSON.parse('{"title":"从知识到实践的学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"学习路线/index.md","filePath":"学习路线/index.md","lastUpdated":1794211306000}'),d={name:"学习路线/index.md"};function n(o,t,p,h,s,l){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="从知识到实践的学习路线" tabindex="-1">从知识到实践的学习路线 <a class="header-anchor" href="#从知识到实践的学习路线" aria-label="Permalink to &quot;从知识到实践的学习路线&quot;">​</a></h1><blockquote><p>当前主线：在已有前端经验上，学习 NestJS、PostgreSQL 与 AI Agent 开发。本站建立知识索引，项目验证想法，博客记录理解与反思。</p></blockquote><h2 id="先选一个真实的小问题" tabindex="-1">先选一个真实的小问题 <a class="header-anchor" href="#先选一个真实的小问题" aria-label="Permalink to &quot;先选一个真实的小问题&quot;">​</a></h2><p>练习是否有价值，不只看它是不是“大项目”。更值得展示的是：<strong>要解决什么问题、为什么这样设计、如何验证、发现了哪些限制。</strong></p><p>建议先围绕一个持续演进的“学习笔记”功能练习：读取笔记 → 创建与修改 → 持久化 → 并发与异常 → 检索 → AI 辅助。每次只补一段可以验证的能力。</p><p>下面是学习建议，不代表这些业务功能已经实现。</p><p>跟课时，可以先读<a href="/FE-prepare-interview/概念与原理/16patterns/s_pn_24-programming_paradigms">编程范式</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_11-layering_dto_dao">DTO / DAO 与分层</a>，再按<a href="/FE-prepare-interview/编码与实践/18nestjs/c_nestjs_1-service_design/c_nestjs_1-service_design">从需求到接口的最小闭环</a>拆解练习；该方案目前处于设计阶段。</p><h2 id="当前路线" tabindex="-1">当前路线 <a class="header-anchor" href="#当前路线" aria-label="Permalink to &quot;当前路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>学习入口</th><th>建议实践</th><th>留下什么证据</th></tr></thead><tbody><tr><td>1. 复用前端经验</td><td><a href="/FE-prepare-interview/概念与原理/11ts/intro">TypeScript</a>、<a href="/FE-prepare-interview/概念与原理/04http/intro">HTTP</a></td><td>写清笔记接口的输入、输出与错误</td><td>类型定义、请求样例、边界说明</td></tr><tr><td>2. 理解服务如何工作</td><td><a href="/FE-prepare-interview/概念与原理/05node/intro">Node.js</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/intro">NestJS</a></td><td>实现一条 Controller → Service 的请求链路</td><td>可运行入口、日志、最小验证步骤</td></tr><tr><td>3. 把数据保存下来</td><td><a href="/FE-prepare-interview/学习自测/19database/q_database_1-postgresql_vs_mysql">数据库选型</a>、<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_8-orm">ORM</a></td><td>用 PostgreSQL 保存笔记，验证字段约束与事务</td><td>表结构、迁移、成功与失败案例</td></tr><tr><td>4. 处理真实边界</td><td><a href="/FE-prepare-interview/学习自测/18nestjs/q_nestjs_6-app_lifecycle">应用生命周期</a>、<a href="/FE-prepare-interview/学习自测/18nestjs/q_nestjs_7-request_lifecycle">请求生命周期</a></td><td>验证校验失败、并发修改、断线与正常停机</td><td>复现步骤、错误响应、测试与复盘</td></tr><tr><td>5. 接入 AI 能力</td><td><a href="/FE-prepare-interview/概念与原理/17ai/s_ai_22-prompt_engineering">Prompt</a>、<a href="/FE-prepare-interview/概念与原理/17ai/s_ai_23-rag">RAG</a>、<a href="/FE-prepare-interview/概念与原理/17ai/s_ai_24-agent">Agent</a></td><td>先做笔记摘要或检索，再尝试有边界的工具调用</td><td>输入输出样例、失败案例、效果与成本</td></tr><tr><td>6. 用数据改进</td><td><a href="/FE-prepare-interview/性能优化/index">性能优化</a></td><td>选一个瓶颈，先测量，再比较改进前后</td><td>环境、基线、测量方法、结果和取舍</td></tr></tbody></table><h2 id="几个项目分别负责什么" tabindex="-1">几个项目分别负责什么？ <a class="header-anchor" href="#几个项目分别负责什么" aria-label="Permalink to &quot;几个项目分别负责什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>载体</th><th>用途</th><th>入口</th></tr></thead><tbody><tr><td>Web 开发学习宝典</td><td>概念、学习自测、路线与实践索引</td><td><a href="/FE-prepare-interview/index">本站首页</a></td></tr><tr><td>AI-Journey-land</td><td>后续重构为全栈与 AI 应用练习载体，逐步关联可运行功能</td><td><a href="https://github.com/Fridolph/AI-Journey-land" target="_blank" rel="noreferrer">GitHub 仓库</a></td></tr><tr><td>个人博客</td><td>把一次实践写成有背景、过程和反思的文章</td><td><a href="https://fridolph.github.io/fridolph-blog/" target="_blank" rel="noreferrer">fridolph-blog</a></td></tr><tr><td>AI Journey Fighting</td><td>记录 AI 原理学习与探索，独立维护、互相引用</td><td><a href="https://fridolph.github.io/AI-Journey-Fighting/" target="_blank" rel="noreferrer">学习站点</a> · <a href="https://github.com/Fridolph/AI-Journey-Fighting" target="_blank" rel="noreferrer">仓库</a></td></tr></tbody></table><p>这里建立的是入口与联系，不表示多个仓库已经合并，也不表示每篇笔记都有对应的实现。具体功能以实践仓库中的代码和说明为准。</p><h2 id="一个知识点怎样形成完整记录" tabindex="-1">一个知识点怎样形成完整记录？ <a class="header-anchor" href="#一个知识点怎样形成完整记录" aria-label="Permalink to &quot;一个知识点怎样形成完整记录？&quot;">​</a></h2><p>以“并发保存笔记”为例，可以逐步串起：</p><ol><li><strong>原理</strong>：理解事务、隔离级别和版本条件更新。</li><li><strong>实践</strong>：在练习项目中模拟两个客户端同时保存。</li><li><strong>验证</strong>：说明期待的行为，记录冲突响应和数据库结果。</li><li><strong>自测</strong>：能否解释为什么事务本身不一定解决覆盖问题？</li><li><strong>复盘</strong>：比较方案、记录失败场景，再链接对应博客文章。</li></ol><p>记录里放具体文件、提交或 PR、运行方法与观察结果，比单纯列一个技术名词更有说服力。</p><h2 id="实践与成果索引" tabindex="-1">实践与成果索引 <a class="header-anchor" href="#实践与成果索引" aria-label="Permalink to &quot;实践与成果索引&quot;">​</a></h2><p>当前已建立 NestJS 和 PostgreSQL 的知识笔记；跨项目 demo 与博客对应关系将随实际完成情况补充。</p><p>新增实践时，使用<a href="./实践记录模板">实践记录模板</a>，按“计划中 / 已运行验证 / 已复盘”标记进度。只有附上可执行步骤与实际结果后，才标记为已验证。</p><h2 id="从旧笔记走向可验证的知识" tabindex="-1">从旧笔记走向可验证的知识 <a class="header-anchor" href="#从旧笔记走向可验证的知识" aria-label="Permalink to &quot;从旧笔记走向可验证的知识&quot;">​</a></h2><p>历史学习素材按主题归入<a href="/FE-prepare-interview/概念与原理/20deploy/intro">开发部署</a>、<a href="/FE-prepare-interview/编码与实践/03algo/intro">算法实践</a>、<a href="/FE-prepare-interview/概念与原理/04http/intro">HTTP</a>、<a href="/FE-prepare-interview/概念与原理/06opt/intro">性能优化</a>和<a href="/FE-prepare-interview/概念与原理/02js/s_js_6-regexp">正则表达式</a>。先读机制，再运行小实验，最后通过<a href="/FE-prepare-interview/学习自测/index">分类自测</a>解释边界。</p><p>每次实践记录具体代码、环境和结果，再连接 AI-Journey-land 与博客；尚未在业务工程运行的方案标记为计划。来源及取舍可查<a href="/FE-prepare-interview/学习资源/笔记迁移记录">历史笔记迁移记录</a>。</p>',22)])])}const g=e(d,[["render",n]]);export{f as __pageData,g as default};
